INSERT INTO lp_knowledge_unit (code, lesson_no, statement, status) VALUES
  ('KT11-C04-TC-001', 10, 'Các tính chất thừa nhận: qua 2 điểm phân biệt có duy nhất 1 đường thẳng; qua 3 điểm không thẳng hàng có duy nhất 1 mặt phẳng; đường thẳng có 2 điểm chung với mặt phẳng thì nằm trong mặt phẳng; hai mặt phẳng phân biệt có điểm chung thì cắt nhau theo một giao tuyến.', 'nhap-tam'),
  ('KT11-C04-PP-001', 10, 'Xác định mặt phẳng: qua 3 điểm không thẳng hàng; qua một đường thẳng và một điểm ngoài nó; qua hai đường thẳng cắt nhau; qua hai đường thẳng song song.', 'nhap-tam'),
  ('KT11-C04-DN-001', 10, 'Hình chóp S.A1...An có đỉnh S, đáy là đa giác A1...An, các mặt bên là tam giác; tứ diện ABCD là hình chóp tam giác.', 'nhap-tam'),
  ('KT11-C04-PP-002', 10, 'Tìm giao tuyến của hai mặt phẳng: tìm hai điểm chung của hai mặt phẳng.', 'nhap-tam'),
  ('KT11-C04-PP-003', 10, 'Tìm giao điểm của d và (P): chọn (Q) chứa d, tìm giao tuyến Δ của (P) và (Q); giao điểm của d và Δ là giao điểm cần tìm.', 'nhap-tam'),
  ('KT11-C04-DN-002', 11, 'Hai đường thẳng trong không gian: cắt nhau, song song (đồng phẳng, không có điểm chung), chéo nhau (không đồng phẳng).', 'nhap-tam'),
  ('KT11-C04-DL-001', 11, 'Định lí về giao tuyến của ba mặt phẳng: ba mặt phẳng đôi một cắt nhau theo ba giao tuyến phân biệt thì ba giao tuyến đồng quy hoặc đôi một song song.', 'nhap-tam'),
  ('KT11-C04-DL-002', 11, 'Hệ quả: hai mặt phẳng cắt nhau lần lượt chứa hai đường thẳng song song thì giao tuyến song song (hoặc trùng) với một trong hai đường thẳng đó.', 'nhap-tam'),
  ('KT11-C04-TC-004', 11, 'Hai đường thẳng phân biệt cùng song song với đường thẳng thứ ba thì song song với nhau.', 'nhap-tam'),
  ('KT11-C04-DN-003', 12, 'Đường thẳng d song song với mặt phẳng (P) nếu chúng không có điểm chung.', 'nhap-tam'),
  ('KT11-C04-DL-003', 12, 'Nếu d không nằm trong (P) và d song song với một đường thẳng a nằm trong (P) thì d song song với (P).', 'nhap-tam'),
  ('KT11-C04-TC-005', 12, 'Nếu d song song với (P) thì mọi mặt phẳng (Q) chứa d mà cắt (P) thì cắt theo giao tuyến song song với d.', 'nhap-tam'),
  ('KT11-C04-DN-004', 13, 'Hai mặt phẳng (P), (Q) song song nếu chúng không có điểm chung.', 'nhap-tam'),
  ('KT11-C04-DL-004', 13, 'Nếu (P) chứa hai đường thẳng cắt nhau cùng song song với (Q) thì (P) song song với (Q).', 'nhap-tam'),
  ('KT11-C04-TC-007', 13, 'Tính chất hai mặt phẳng song song: qua điểm ngoài (Q) có duy nhất (P) song song (Q); (P)∥(Q) thì mọi đường thẳng trong (P) song song (Q); mặt phẳng cắt hai mặt phẳng song song theo hai giao tuyến song song.', 'nhap-tam'),
  ('KT11-C04-DL-005', 13, 'Định lí Thalès trong không gian: ba mặt phẳng đôi một song song chắn trên hai cát tuyến bất kì những đoạn thẳng tương ứng tỉ lệ.', 'nhap-tam'),
  ('KT11-C04-DN-005', 13, 'Hình lăng trụ có hai đáy nằm trên hai mặt phẳng song song, các cạnh bên song song và bằng nhau, mặt bên là hình bình hành; hình hộp là hình lăng trụ có đáy là hình bình hành.', 'nhap-tam'),
  ('KT11-C04-DN-006', 14, 'Phép chiếu song song lên (P) theo phương Δ (Δ cắt (P)): mỗi điểm M ứng với giao điểm M'' của (P) và đường thẳng qua M song song (hoặc trùng) với Δ.', 'nhap-tam'),
  ('KT11-C04-TC-008', 14, 'Phép chiếu song song giữ tính thẳng hàng và thứ tự điểm, biến hai đường thẳng song song thành hai đường thẳng song song hoặc trùng, giữ tỉ số độ dài hai đoạn thẳng cùng nằm trên một đường thẳng hoặc trên hai đường thẳng song song.', 'nhap-tam'),
  ('KT11-C04-PP-004', 14, 'Hình biểu diễn của hình không gian là hình chiếu song song của nó lên một mặt phẳng; giữ quan hệ song song, tỉ số, trung điểm.', 'nhap-tam'),
  ('KT11-C07-DN-001', 22, 'Góc giữa hai đường thẳng a, b là góc giữa hai đường thẳng a'', b'' cùng đi qua một điểm và lần lượt song song (hoặc trùng) với a, b; số đo từ 0° đến 90°.', 'nhap-tam'),
  ('KT11-C07-DN-002', 22, 'Hai đường thẳng vuông góc nếu góc giữa chúng bằng 90°; chúng có thể chéo nhau.', 'nhap-tam'),
  ('KT11-C07-CT-001', 22, '$\cos(a,b)=\dfrac{|\vec u\cdot\vec v|}{|\vec u|\cdot|\vec v|}$ với $\vec u,\vec v$ là vectơ chỉ phương.', 'nhap-tam'),
  ('KT11-C07-TC-001', 22, 'Nếu a ∥ b và c ⊥ a thì c ⊥ b.', 'nhap-tam'),
  ('KT11-C07-DN-003', 23, 'Đường thẳng d vuông góc với (P) nếu d vuông góc với mọi đường thẳng nằm trong (P).', 'nhap-tam'),
  ('KT11-C07-DL-001', 23, 'Nếu d vuông góc với hai đường thẳng cắt nhau cùng nằm trong (P) thì d ⊥ (P).', 'nhap-tam'),
  ('KT11-C07-TC-002', 23, 'a ∥ b, (P) ⊥ a thì (P) ⊥ b; a ⊥ (P), b ⊥ (P) thì a ∥ b (hoặc trùng); (P) ∥ (Q), d ⊥ (P) thì d ⊥ (Q).', 'nhap-tam'),
  ('KT11-C07-DN-004', 23, 'Mặt phẳng trung trực của AB là mặt phẳng vuông góc với AB tại trung điểm; là tập hợp các điểm cách đều A và B.', 'nhap-tam'),
  ('KT11-C07-DL-002', 23, 'Định lí ba đường vuông góc: a nằm trong (P), b là hình chiếu vuông góc của d lên (P); a ⊥ d khi và chỉ khi a ⊥ b.', 'nhap-tam'),
  ('KT11-C07-DN-005', 24, 'Phép chiếu vuông góc lên (P) là phép chiếu song song theo phương vuông góc với (P).', 'nhap-tam'),
  ('KT11-C07-DN-006', 24, 'Góc giữa d và (P): 90° nếu d ⊥ (P); 0° nếu d ∥ (P) hoặc d ⊂ (P); còn lại là góc giữa d và hình chiếu d'' của nó trên (P).', 'nhap-tam'),
  ('KT11-C07-CT-002', 24, 'Nếu $SH\perp(P)$, $H,A\in(P)$ thì góc giữa $SA$ và $(P)$ là $\widehat{SAH}$, $\sin\varphi=\dfrac{SH}{SA}$.', 'nhap-tam'),
  ('KT11-C07-DN-007', 25, 'Góc nhị diện gồm hai nửa mặt phẳng chung cạnh c; góc phẳng nhị diện là góc giữa hai tia cùng vuông góc với c tại một điểm, mỗi tia nằm trong một nửa mặt phẳng.', 'nhap-tam'),
  ('KT11-C07-DN-008', 25, 'Góc giữa hai mặt phẳng cắt nhau có số đo từ 0° đến 90°; (P) ⊥ (Q) nếu góc giữa chúng bằng 90°.', 'nhap-tam'),
  ('KT11-C07-DL-003', 25, 'Nếu (P) chứa một đường thẳng vuông góc với (Q) thì (P) ⊥ (Q).', 'nhap-tam'),
  ('KT11-C07-TC-003', 25, '(P) ⊥ (Q) theo giao tuyến c: đường thẳng a nằm trong (P), a ⊥ c thì a ⊥ (Q); hai mặt phẳng cắt nhau cùng vuông góc mặt phẳng thứ ba thì giao tuyến vuông góc mặt phẳng ấy.', 'nhap-tam'),
  ('KT11-C07-DN-009', 25, 'Lăng trụ đứng có cạnh bên vuông góc với đáy; hình chóp đều có đáy là đa giác đều và chân đường cao là tâm đáy.', 'nhap-tam'),
  ('KT11-C07-DN-010', 26, 'd(M,Δ)=MH với H là chân đường vuông góc hạ từ M xuống Δ; d(M,(P))=MH với H là hình chiếu vuông góc của M lên (P).', 'nhap-tam'),
  ('KT11-C07-DN-011', 26, 'Khoảng cách giữa đường thẳng và mặt phẳng song song, giữa hai mặt phẳng song song bằng khoảng cách từ một điểm bất kì của đối tượng này đến đối tượng kia.', 'nhap-tam'),
  ('KT11-C07-DN-012', 26, 'Khoảng cách giữa hai đường thẳng chéo nhau là độ dài đoạn vuông góc chung.', 'nhap-tam'),
  ('KT11-C07-PP-001', 26, 'Đưa khoảng cách hai đường chéo nhau về khoảng cách điểm–mặt: $d(a,b)=d(a,(P))$ với $(P)\supset b$, $(P)\parallel a$.', 'nhap-tam'),
  ('KT11-C07-CT-003', 26, 'Nếu $SA\perp(ABC)$, $AK\perp BC$, $AH\perp SK$ thì $AH\perp(SBC)$ và $\dfrac1{AH^2}=\dfrac1{SA^2}+\dfrac1{AK^2}$.', 'nhap-tam'),
  ('KT11-C07-CT-004', 27, 'Thể tích lăng trụ $V=S_{đáy}\cdot h$; hình hộp chữ nhật $V=abc$; hình lập phương $V=a^3$.', 'nhap-tam'),
  ('KT11-C07-CT-005', 27, 'Thể tích khối chóp $V=\dfrac13S_{đáy}\cdot h$.', 'nhap-tam'),
  ('KT11-C07-CT-006', 27, 'Thể tích khối chóp cụt đều $V=\dfrac h3\left(S+\sqrt{SS''}+S''\right)$.', 'nhap-tam'),
  ('KT11-C07-CT-007', 27, 'Tỉ số thể tích: $\dfrac{V_{S.A''B''C''}}{V_{S.ABC}}=\dfrac{SA''}{SA}\cdot\dfrac{SB''}{SB}\cdot\dfrac{SC''}{SC}$.', 'nhap-tam'),
  ('KT11-C07-PP-002', 27, 'Tính thể tích: xác định chiều cao (chân đường vuông góc) và diện tích đáy; dùng tỉ số thể tích hoặc khoảng cách điểm–mặt khi chiều cao khó thấy.', 'nhap-tam'),
  ('KT11-C05-DN-001', 15, 'Dãy $(u_n)$ có giới hạn $L$ ($\lim u_n=L$) nếu $|u_n-L|$ nhỏ tuỳ ý khi $n$ đủ lớn.', 'nhap-tam'),
  ('KT11-C05-CT-001', 15, 'Giới hạn cơ bản: $\lim\dfrac1{n^k}=0$ ($k>0$); $\lim q^n=0$ khi $|q|<1$; $\lim c=c$.', 'nhap-tam'),
  ('KT11-C05-TC-001', 15, 'Nếu $\lim u_n=a$, $\lim v_n=b$ thì $\lim(u_n\pm v_n)=a\pm b$, $\lim u_nv_n=ab$, $\lim\dfrac{u_n}{v_n}=\dfrac ab$ ($b\ne0$).', 'nhap-tam'),
  ('KT11-C05-CT-002', 15, 'Tổng cấp số nhân lùi vô hạn ($|q|<1$): $S=\dfrac{u_1}{1-q}$.', 'nhap-tam'),
  ('KT11-C05-PP-001', 15, 'Khử dạng vô định của dãy: chia tử và mẫu cho luỹ thừa bậc cao nhất của n, hoặc nhân liên hợp.', 'nhap-tam'),
  ('KT11-C05-DN-002', 16, '$\lim_{x\to x_0}f(x)=L$ nếu mọi dãy $x_n\to x_0$ ($x_n\ne x_0$) đều có $f(x_n)\to L$.', 'nhap-tam'),
  ('KT11-C05-DL-001', 16, '$\lim_{x\to x_0}f(x)=L$ khi và chỉ khi $\lim_{x\to x_0^+}f(x)=\lim_{x\to x_0^-}f(x)=L$.', 'nhap-tam'),
  ('KT11-C05-PP-002', 16, 'Dạng vô định: $\dfrac00$ phân tích nhân tử hoặc nhân liên hợp; $\dfrac\infty\infty$ chia cho luỹ thừa bậc cao nhất; $\infty-\infty$ quy đồng hoặc liên hợp.', 'nhap-tam'),
  ('KT11-C05-DN-003', 17, '$f$ liên tục tại $x_0$ nếu $\lim_{x\to x_0}f(x)=f(x_0)$.', 'nhap-tam'),
  ('KT11-C05-TC-002', 17, 'Đa thức, phân thức hữu tỉ, hàm lượng giác, căn thức liên tục trên tập xác định; tổng, hiệu, tích, thương (mẫu khác 0) của hàm liên tục là hàm liên tục.', 'nhap-tam'),
  ('KT11-C05-DL-002', 17, 'Nếu $f$ liên tục trên $[a;b]$ và $f(a)f(b)<0$ thì phương trình $f(x)=0$ có ít nhất một nghiệm thuộc $(a;b)$.', 'nhap-tam'),
  ('KT11-C06-DN-001', 18, 'Luỹ thừa: $a^0=1$ ($a\ne0$), $a^{-n}=\dfrac1{a^n}$; $a^{\frac mn}=\sqrt[n]{a^m}$ ($a>0$).', 'nhap-tam'),
  ('KT11-C06-TC-001', 18, 'Với $a,b>0$: $a^\alpha a^\beta=a^{\alpha+\beta}$; $\dfrac{a^\alpha}{a^\beta}=a^{\alpha-\beta}$; $(a^\alpha)^\beta=a^{\alpha\beta}$; $(ab)^\alpha=a^\alpha b^\alpha$.', 'nhap-tam'),
  ('KT11-C06-TC-002', 18, 'So sánh: $a>1$ thì $a^\alpha<a^\beta\Leftrightarrow\alpha<\beta$; $0<a<1$ thì ngược lại.', 'nhap-tam'),
  ('KT11-C06-DN-002', 19, 'Với $a>0$, $a\ne1$, $b>0$: $\log_ab=\alpha\Leftrightarrow a^\alpha=b$; $\lg b=\log_{10}b$, $\ln b=\log_eb$.', 'nhap-tam'),
  ('KT11-C06-TC-003', 19, 'Với $M,N>0$: $\log_a(MN)=\log_aM+\log_aN$; $\log_a\dfrac MN=\log_aM-\log_aN$; $\log_aM^\alpha=\alpha\log_aM$.', 'nhap-tam'),
  ('KT11-C06-CT-001', 19, 'Đổi cơ số: $\log_ab=\dfrac{\log_cb}{\log_ca}$; $\log_ab=\dfrac1{\log_ba}$.', 'nhap-tam'),
  ('KT11-C06-DN-003', 20, 'Hàm số mũ $y=a^x$ ($a>0,a\ne1$): tập xác định $\mathbb R$, tập giá trị $(0;+\infty)$, đồng biến khi $a>1$, nghịch biến khi $0<a<1$.', 'nhap-tam'),
  ('KT11-C06-DN-004', 20, 'Hàm số lôgarit $y=\log_ax$: tập xác định $(0;+\infty)$, tập giá trị $\mathbb R$, đồng biến khi $a>1$, nghịch biến khi $0<a<1$.', 'nhap-tam'),
  ('KT11-C06-PP-001', 21, 'Phương trình mũ: $a^x=b$ ($b>0$) $\Leftrightarrow x=\log_ab$; $a^{f(x)}=a^{g(x)}\Leftrightarrow f(x)=g(x)$; có thể đặt $t=a^x>0$.', 'nhap-tam'),
  ('KT11-C06-PP-002', 21, 'Phương trình lôgarit: $\log_ax=b\Leftrightarrow x=a^b$; $\log_af(x)=\log_ag(x)\Leftrightarrow f(x)=g(x)>0$; phải đặt điều kiện.', 'nhap-tam'),
  ('KT11-C06-TC-004', 21, 'Bất phương trình: $a>1$ thì $a^{f}>a^{g}\Leftrightarrow f>g$; $0<a<1$ thì đổi chiều.', 'nhap-tam'),
  ('KT11-C09-DN-001', 31, '$f''(x_0)=\lim_{x\to x_0}\dfrac{f(x)-f(x_0)}{x-x_0}$.', 'nhap-tam'),
  ('KT11-C09-TC-001', 31, 'Hàm số có đạo hàm tại $x_0$ thì liên tục tại $x_0$; điều ngược lại không đúng.', 'nhap-tam'),
  ('KT11-C09-CT-001', 31, 'Phương trình tiếp tuyến tại $M(x_0;f(x_0))$: $y=f''(x_0)(x-x_0)+f(x_0)$; $f''(x_0)$ là hệ số góc.', 'nhap-tam'),
  ('KT11-C09-DN-002', 31, 'Ý nghĩa vật lí: vận tốc tức thời $v(t_0)=s''(t_0)$.', 'nhap-tam'),
  ('KT11-C09-CT-002', 32, '$(c)''=0$; $(x^n)''=nx^{n-1}$; $(\sqrt x)''=\dfrac1{2\sqrt x}$; $\left(\dfrac1x\right)''=-\dfrac1{x^2}$.', 'nhap-tam'),
  ('KT11-C09-CT-003', 32, '$(\sin x)''=\cos x$; $(\cos x)''=-\sin x$; $(\tan x)''=\dfrac1{\cos^2x}$; $(\cot x)''=-\dfrac1{\sin^2x}$.', 'nhap-tam'),
  ('KT11-C09-CT-004', 32, '$(e^x)''=e^x$; $(a^x)''=a^x\ln a$; $(\ln x)''=\dfrac1x$; $(\log_ax)''=\dfrac1{x\ln a}$.', 'nhap-tam'),
  ('KT11-C09-CT-005', 32, '$(u\pm v)''=u''\pm v''$; $(uv)''=u''v+uv''$; $\left(\dfrac uv\right)''=\dfrac{u''v-uv''}{v^2}$.', 'nhap-tam'),
  ('KT11-C09-CT-006', 32, 'Đạo hàm hàm hợp: $y=f(u(x))\Rightarrow y''_x=f''_u\cdot u''_x$.', 'nhap-tam'),
  ('KT11-C09-DN-003', 33, 'Đạo hàm cấp hai $f''''(x)=(f''(x))''$.', 'nhap-tam'),
  ('KT11-C09-DN-004', 33, 'Ý nghĩa cơ học: gia tốc $a(t)=v''(t)=s''''(t)$.', 'nhap-tam')
INSERT INTO lp_exercise (code, lesson_no, level, statement, answer, source) VALUES
  ('BT11-B10-1', 10, 'NB', 'Qua 4 điểm không đồng phẳng có bao nhiêu mặt phẳng đi qua 3 trong 4 điểm?', NULL, 'lop-11/bai-tap'),
  ('BT11-B10-2', 10, 'NB', 'Hình chóp có đáy lục giác có bao nhiêu mặt?', NULL, 'lop-11/bai-tap'),
  ('BT11-B10-3', 10, 'NB', '*[Trắc nghiệm]* Hình chóp có đáy là ngũ giác có tất cả bao nhiêu cạnh? A. $5$; B. $10$; C. $6$; D. $15$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B10-4', 10, 'TH', 'Chóp $S.ABCD$ đáy là hình bình hành. Tìm $(SAB)\cap(SCD)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B10-5', 10, 'TH', '*[Đúng/sai]* Cho tứ diện $ABCD$, $M\in AB$, $N\in AC$ ($M,N$ khác $A$). a) $M,N,B,C$ đồng phẳng; b) $MN$ và $BC$ luôn cắt nhau; c) $(DMN)\cap(ABC)=MN$; d) $A,M,N,D$ đồng phẳng.', NULL, 'lop-11/bai-tap'),
  ('BT11-B10-6', 10, 'VD', 'Chóp $S.ABCD$ đáy là hình bình hành tâm $O$; $M$ là trung điểm $SC$. Tìm giao điểm $I$ của $AM$ và $(SBD)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B10-7', 10, 'VDC', 'Cho tứ diện $ABCD$, $M\in AB$, $N\in AC$ sao cho $MN\not\parallel BC$. Tìm giao tuyến của $(DMN)$ và $(DBC)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B11-1', 11, 'NB', 'Hai đường thẳng không có điểm chung có song song không?', NULL, 'lop-11/bai-tap'),
  ('BT11-B11-2', 11, 'NB', '*[Trắc nghiệm]* Hai đường thẳng phân biệt cùng song song với một đường thẳng thứ ba thì: A. chéo nhau; B. cắt nhau; C. song song với nhau; D. có thể cắt nhau.', NULL, 'lop-11/bai-tap'),
  ('BT11-B11-3', 11, 'TH', 'Tứ diện $ABCD$, $M,N$ là trung điểm $AB,AC$. Chứng minh $MN\parallel BC$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B11-4', 11, 'VD', 'Chóp $S.ABCD$ đáy hình thang $AB\parallel CD$. Tìm $(SAB)\cap(SCD)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B11-5', 11, 'VD', 'Chóp $S.ABCD$ đáy hình bình hành. $M,N$ là trung điểm $SA,SB$. Chứng minh $MN\parallel CD$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B11-6', 11, 'VD', '*[Trả lời ngắn]* Tứ diện $ABCD$ có $M,N,P,Q$ lần lượt là trung điểm $AB,BC,CD,DA$; $AC=6$, $BD=8$. Tính chu vi tứ giác $MNPQ$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B11-7', 11, 'VDC', 'Tứ diện $ABCD$, $G_1,G_2$ là trọng tâm $\triangle ABC$, $\triangle ABD$. Chứng minh $G_1G_2\parallel CD$ và tính $\dfrac{G_1G_2}{CD}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B12-1', 12, 'NB', 'Cho $a\parallel b$, $b\subset(P)$, $a\not\subset(P)$. Kết luận?', NULL, 'lop-11/bai-tap'),
  ('BT11-B12-2', 12, 'TH', 'Tứ diện $ABCD$, $I,J$ trung điểm $AB,AC$. Chứng minh $IJ\parallel(BCD)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B12-3', 12, 'TH', '*[Đúng/sai]* Cho đường thẳng $a\parallel(P)$. a) Mọi đường thẳng nằm trong $(P)$ đều song song $a$; b) trong $(P)$ có vô số đường thẳng song song $a$; c) nếu $(Q)\supset a$ và $(Q)\cap(P)=b$ thì $b\parallel a$; d) $a$ và $(P)$ có đúng một điểm chung.', NULL, 'lop-11/bai-tap'),
  ('BT11-B12-4', 12, 'VD', 'Chóp $S.ABCD$ đáy hình bình hành. Chứng minh $AB\parallel(SCD)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B12-5', 12, 'VD', 'Chóp $S.ABCD$ đáy hình bình hành, $M$ là trung điểm $SA$. Chứng minh $SC\parallel(MBD)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B12-6', 12, 'VD', '*[Trả lời ngắn]* Tứ diện $ABCD$; $M\in AB$, $N\in AC$ với $\dfrac{AM}{AB}=\dfrac{AN}{AC}=\dfrac23$; $BC=9$. Tính $MN$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B12-7', 12, 'VDC', 'Tứ diện $ABCD$, $M\in AB$. Mặt phẳng $(\alpha)$ qua $M$ song song $BC$ và $AD$. Tìm thiết diện của $(\alpha)$ với tứ diện.', NULL, 'lop-11/bai-tap'),
  ('BT11-B13-1', 13, 'NB', 'Hai mặt phẳng phân biệt không cắt nhau thì?', NULL, 'lop-11/bai-tap'),
  ('BT11-B13-2', 13, 'NB', '*[Trắc nghiệm]* Nếu $(P)\parallel(Q)$ và đường thẳng $a\subset(P)$ thì: A. $a\parallel(Q)$; B. $a$ cắt $(Q)$; C. $a\subset(Q)$; D. $a$ và $(Q)$ chéo nhau.', NULL, 'lop-11/bai-tap'),
  ('BT11-B13-3', 13, 'TH', 'Hình hộp $ABCD.A''B''C''D''$. Chứng minh $(ABB''A'')\parallel(CDD''C'')$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B13-4', 13, 'VD', 'Lăng trụ $ABC.A''B''C''$. Chứng minh $(ABC)\parallel(A''B''C'')$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B13-5', 13, 'VD', 'Ba mặt phẳng song song cắt hai cát tuyến tại $A,B,C$ và $A'',B'',C''$. Biết $AB=3$, $BC=5$, $A''B''=4{,}5$. Tính $B''C''$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B13-6', 13, 'VD', '*[Trả lời ngắn]* Ba mặt phẳng song song $(P),(Q),(R)$ cắt hai cát tuyến lần lượt tại $A,B,C$ và $A'',B'',C''$. Biết $\dfrac{AB}{BC}=\dfrac23$ và $A''C''=15$. Tính $A''B''$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B13-7', 13, 'VDC', 'Hình hộp $ABCD.A''B''C''D''$. Chứng minh $(AB''D'')\parallel(C''BD)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B14-1', 14, 'NB', 'Phép chiếu song song có giữ trung điểm đoạn thẳng không?', NULL, 'lop-11/bai-tap'),
  ('BT11-B14-2', 14, 'NB', '*[Trắc nghiệm]* Phép chiếu song song biến hai đường thẳng song song (không song song với phương chiếu) thành: A. hai đường thẳng song song hoặc trùng nhau; B. hai đường thẳng cắt nhau; C. hai đường thẳng chéo nhau; D. luôn là hai đường thẳng song song phân biệt.', NULL, 'lop-11/bai-tap'),
  ('BT11-B14-3', 14, 'TH', 'Hình vuông có hình biểu diễn là hình nào?', NULL, 'lop-11/bai-tap'),
  ('BT11-B14-4', 14, 'TH', '*[Đúng/sai]* Về phép chiếu song song: a) giữ tỉ số độ dài hai đoạn thẳng cùng nằm trên một đường thẳng; b) hình chiếu của trung điểm một đoạn thẳng là trung điểm hình chiếu của đoạn thẳng; c) hình chiếu của hình tròn luôn là hình tròn; d) hình chiếu của góc $60^\circ$ luôn có số đo $60^\circ$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B14-5', 14, 'VD', '$M$ thuộc đoạn $AB$, $MA=2MB$. Hình chiếu $M''$ trên $A''B''$ có $M''A''$ gấp mấy lần $M''B''$?', NULL, 'lop-11/bai-tap'),
  ('BT11-B14-6', 14, 'VD', '*[Trả lời ngắn]* Tam giác $ABC$ có hình biểu diễn $A''B''C''$. Điểm $M\in AB$ với $AM=3MB$; $A''B''=12$. Tính $A''M''$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B14-7', 14, 'VDC', 'Vì sao hình biểu diễn của tam giác đều nói chung không phải là tam giác đều?', NULL, 'lop-11/bai-tap'),
  ('BT11-B15-1', 15, 'NB', '$\lim\dfrac{2n+1}{n}$?', NULL, 'lop-11/bai-tap'),
  ('BT11-B15-2', 15, 'NB', '*[Trắc nghiệm]* $\lim\left(-\dfrac12\right)^n$ bằng: A. $0$; B. $-\dfrac12$; C. $1$; D. $-\infty$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B15-3', 15, 'TH', '$\lim\dfrac{n^2-3n}{4n^2+5}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B15-4', 15, 'TH', '$\lim\dfrac{3^n+2^n}{3^{n+1}}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B15-5', 15, 'VD', 'Tính $\lim\left(\sqrt{n^2+n}-n\right)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B15-6', 15, 'VD', 'Tính $S=1+\tfrac12+\tfrac14+\dots$ (tổng vô hạn).', NULL, 'lop-11/bai-tap'),
  ('BT11-B15-7', 15, 'VD', '*[Trả lời ngắn]* Tính $\lim\left(\sqrt{4n^2+n}-2n\right)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B15-8', 15, 'VDC', 'Biểu diễn số thập phân vô hạn tuần hoàn $0{,}\overline{36}$ thành phân số.', NULL, 'lop-11/bai-tap'),
  ('BT11-B16-1', 16, 'NB', '$\lim_{x\to1}(x^2+3x)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B16-2', 16, 'TH', '$\lim_{x\to3}\dfrac{x^2-9}{x-3}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B16-3', 16, 'TH', '$\lim_{x\to+\infty}\dfrac{2x^2+x}{x^2-1}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B16-4', 16, 'TH', '*[Đúng/sai]* a) $\lim_{x\to2}(x^2-x)=2$; b) $\lim_{x\to+\infty}(x^3-3x)=+\infty$; c) $\lim_{x\to-\infty}(x^3+1)=+\infty$; d) $\lim_{x\to2^-}\dfrac1{x-2}=-\infty$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B16-5', 16, 'VD', 'Tính $\lim_{x\to1^+}\dfrac{x+1}{x-1}$ và $\lim_{x\to1^-}\dfrac{x+1}{x-1}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B16-6', 16, 'VD', 'Tính $\lim_{x\to0}\dfrac{\sqrt{1+x}-1}{x}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B16-7', 16, 'VD', '*[Trả lời ngắn]* Tính $\lim_{x\to1}\dfrac{x^2-1}{x^3-1}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B16-8', 16, 'VDC', 'Tính $\lim_{x\to+\infty}\left(\sqrt{x^2+2x}-x\right)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B17-1', 17, 'NB', '$f(x)=\dfrac{1}{x-2}$ liên tục trên tập nào?', NULL, 'lop-11/bai-tap'),
  ('BT11-B17-2', 17, 'NB', '*[Trắc nghiệm]* Hàm số nào liên tục trên $\mathbb R$? A. $y=\dfrac1x$; B. $y=\tan x$; C. $y=x^3-x+1$; D. $y=\sqrt x$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B17-3', 17, 'TH', 'Xét tính liên tục tại $x=1$ của $f(x)=\begin{cases}\dfrac{x^2-1}{x-1}&x\ne1\\ 2&x=1\end{cases}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B17-4', 17, 'TH', 'Tìm $m$ để $f(x)=\begin{cases}x+1&x<2\\ mx-1&x\ge2\end{cases}$ liên tục tại 2.', NULL, 'lop-11/bai-tap'),
  ('BT11-B17-5', 17, 'VD', 'Chứng minh phương trình $x^3-3x+1=0$ có ba nghiệm phân biệt.', NULL, 'lop-11/bai-tap'),
  ('BT11-B17-6', 17, 'VD', '*[Trả lời ngắn]* Tìm $m$ để $f(x)=\begin{cases}x^2+m&x<1\\ 2x+3&x\ge1\end{cases}$ liên tục tại $x=1$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B17-7', 17, 'VDC', 'Chứng minh phương trình $\cos x=x$ có nghiệm trong khoảng $\left(0;\dfrac\pi2\right)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B18-1', 18, 'NB', 'Tính $8^{2/3}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B18-2', 18, 'NB', '*[Trắc nghiệm]* Giá trị của $16^{3/4}$ là: A. $8$; B. $12$; C. $6$; D. $64$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B18-3', 18, 'TH', 'Rút gọn $\dfrac{a^{\sqrt3+1}\cdot a^{2-\sqrt3}}{(a^{\sqrt2-1})^{\sqrt2+1}}$ ($a>0$).', NULL, 'lop-11/bai-tap'),
  ('BT11-B18-4', 18, 'TH', '*[Đúng/sai]* Với $a>0$: a) $a^{1/2}\cdot a^{1/3}=a^{5/6}$; b) $\left(a^{\sqrt2}\right)^{\sqrt2}=a^2$; c) $2^{-3}=-8$; d) $\left(a^3\right)^{-1/3}=a^{-1}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B18-5', 18, 'VD', 'So sánh $\left(\tfrac13\right)^{\sqrt2}$ và $\left(\tfrac13\right)^{1{,}5}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B18-6', 18, 'VD', '*[Trả lời ngắn]* Với $a>0$, viết $\sqrt{a^3\sqrt[3]{a^2}}$ dưới dạng $a^{m/n}$ ($\dfrac mn$ tối giản). Tính $m+n$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B18-7', 18, 'VDC', 'Cho $x>0$, $x+x^{-1}=7$. Tính $x^{1/2}+x^{-1/2}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B19-1', 19, 'NB', '$\log_2 32$?', NULL, 'lop-11/bai-tap'),
  ('BT11-B19-2', 19, 'NB', '*[Trắc nghiệm]* Giá trị của $\log_2\dfrac18$ là: A. $-3$; B. $3$; C. $\dfrac13$; D. $-\dfrac13$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B19-3', 19, 'TH', 'Cho $\log_23=a$. Tính $\log_{12}18$ theo $a$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B19-4', 19, 'TH', '*[Đúng/sai]* a) $\log_212=2+\log_23$; b) $\log_35\cdot\log_59=2$; c) $\lg100=3$; d) $\log_ab^2=2\log_ab$ với $a>0,a\ne1,b>0$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B19-5', 19, 'VD', 'Tính $A=\log_26+\log_2\dfrac13$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B19-6', 19, 'VD', '*[Trả lời ngắn]* Tính $B=2\log_36-\log_34$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B19-7', 19, 'VDC', 'Độ pH được tính bởi $\mathrm{pH}=-\lg[H^+]$. Tìm pH khi $[H^+]=10^{-7}$ và khi $[H^+]=4\cdot10^{-5}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B20-1', 20, 'NB', 'TXĐ của $y=\log_3(x-2)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B20-2', 20, 'NB', '*[Trắc nghiệm]* Hàm số $y=2^x$: A. đồng biến trên $\mathbb R$; B. nghịch biến trên $\mathbb R$; C. đồng biến trên $(0;+\infty)$ và nghịch biến trên $(-\infty;0)$; D. có tập giá trị là $\mathbb R$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B20-3', 20, 'TH', 'So sánh $\log_{0,5}3$ và $\log_{0,5}5$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B20-4', 20, 'TH', '*[Đúng/sai]* Cho $y=\log_{1/2}x$. a) Tập xác định là $(0;+\infty)$; b) hàm số nghịch biến trên tập xác định; c) đồ thị đi qua điểm $(1;0)$; d) $\log_{1/2}2>0$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B20-5', 20, 'VD', 'Tìm TXĐ của $y=\log_2(x^2-4x+3)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B20-6', 20, 'VD', '*[Trả lời ngắn]* Với $x$ thuộc tập xác định của $y=\ln(6-x)+\sqrt{x-1}$, có bao nhiêu giá trị nguyên của $x$?', NULL, 'lop-11/bai-tap'),
  ('BT11-B20-7', 20, 'VDC', 'Vi khuẩn tăng gấp đôi sau mỗi $3$ giờ, ban đầu có $500$ con. Số vi khuẩn sau $t$ giờ? Sau bao lâu đạt $16\,000$ con?', NULL, 'lop-11/bai-tap'),
  ('BT11-B21-1', 21, 'NB', '$2^x=8$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B21-2', 21, 'NB', '*[Trắc nghiệm]* Nghiệm của phương trình $\log_3x=2$ là: A. $x=6$; B. $x=9$; C. $x=8$; D. $x=\dfrac23$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B21-3', 21, 'TH', '$\log_2(x-1)=3$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B21-4', 21, 'TH', '$4^x-3\cdot2^x+2=0$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B21-5', 21, 'VD', 'Giải $\log_2x+\log_2(x-3)=2$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B21-6', 21, 'VD', 'Giải bất phương trình $\left(\tfrac12\right)^{x}>\tfrac14$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B21-7', 21, 'VDC', 'Gửi $200$ triệu đồng, lãi $7\%$/năm (lãi nhập gốc). Sau ít nhất bao nhiêu năm số tiền vượt $300$ triệu?', NULL, 'lop-11/bai-tap'),
  ('BT11-B21-8', 21, 'VDC', '*[Trả lời ngắn]* Tìm giá trị nguyên lớn nhất của $m$ để phương trình $4^x-2^{x+1}+m=0$ có nghiệm thực.', NULL, 'lop-11/bai-tap'),
  ('BT11-B22-1', 22, 'NB', 'Góc giữa $AB$ và $CD$ trong hình lập phương $ABCD.A''B''C''D''$?', NULL, 'lop-11/bai-tap'),
  ('BT11-B22-2', 22, 'NB', '*[Trắc nghiệm]* Trong hình lập phương $ABCD.A''B''C''D''$, góc giữa $AB$ và $A''D''$ bằng: A. $0^\circ$; B. $45^\circ$; C. $60^\circ$; D. $90^\circ$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B22-3', 22, 'TH', 'Hình lập phương $ABCD.A''B''C''D''$. Tính góc giữa $AB''$ và $BC''$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B22-4', 22, 'TH', '*[Đúng/sai]* Hình lập phương $ABCD.A''B''C''D''$. a) $AC\perp BD$; b) $AC\perp B''D''$; c) góc giữa $AC$ và $A''D$ bằng $60^\circ$; d) góc giữa $BD''$ và $AC$ bằng $60^\circ$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B22-5', 22, 'VD', 'Tứ diện đều $ABCD$ cạnh $a$. Chứng minh $AB\perp CD$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B22-6', 22, 'VD', '*[Trả lời ngắn]* Tứ diện đều $ABCD$ cạnh $a$, $M$ là trung điểm $BC$. Tính $\cos$ góc giữa $AB$ và $DM$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B22-7', 22, 'VDC', 'Tứ diện $ABCD$ có $AB=CD=a$; $M,N$ lần lượt là trung điểm $BC,AD$ và $MN=\dfrac{a\sqrt3}{2}$. Tính góc giữa $AB$ và $CD$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B23-1', 23, 'NB', '$d\perp(P)$ thì $d$ vuông góc với bao nhiêu đường thẳng trong $(P)$?', NULL, 'lop-11/bai-tap'),
  ('BT11-B23-2', 23, 'NB', '*[Trắc nghiệm]* Điều kiện đủ để đường thẳng $d$ vuông góc với mặt phẳng $(P)$ là: A. $d$ vuông góc với một đường thẳng nằm trong $(P)$; B. $d$ vuông góc với hai đường thẳng cắt nhau nằm trong $(P)$; C. $d$ vuông góc với hai đường thẳng song song nằm trong $(P)$; D. $d$ song song với một đường thẳng nằm trong $(P)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B23-3', 23, 'TH', 'Chóp $S.ABCD$ đáy là hình vuông, $SA\perp(ABCD)$. Chứng minh $BC\perp(SAB)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B23-4', 23, 'TH', '*[Đúng/sai]* Chóp $S.ABCD$ đáy hình vuông, $SA\perp(ABCD)$. a) $SA\perp BD$; b) $CD\perp(SAD)$; c) $BD\perp SC$; d) $AC\perp(SBD)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B23-5', 23, 'VD', 'Với giả thiết trên (chóp $S.ABCD$ đáy hình vuông, $SA\perp(ABCD)$), chứng minh $BD\perp(SAC)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B23-6', 23, 'VD', 'Chóp $S.ABC$ có $SA=SB=SC$, $H$ là tâm đường tròn ngoại tiếp $\triangle ABC$. Chứng minh $SH\perp(ABC)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B23-7', 23, 'VDC', 'Tứ diện $OABC$ có $OA,OB,OC$ đôi một vuông góc, $H$ là trực tâm $\triangle ABC$. Chứng minh $OH\perp(ABC)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B24-1', 24, 'NB', 'Hình chiếu vuông góc của điểm $S$ lên $(ABC)$ là gì?', NULL, 'lop-11/bai-tap'),
  ('BT11-B24-2', 24, 'NB', '*[Trắc nghiệm]* Góc giữa đường thẳng $d$ và mặt phẳng $(P)$ khi $d\perp(P)$ bằng: A. $0^\circ$; B. $45^\circ$; C. $60^\circ$; D. $90^\circ$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B24-3', 24, 'TH', 'Chóp $S.ABCD$ đáy hình vuông cạnh $a$, $SA\perp(ABCD)$, $SA=a$. Tính góc giữa $SC$ và mặt đáy.', NULL, 'lop-11/bai-tap'),
  ('BT11-B24-4', 24, 'TH', '*[Đúng/sai]* Chóp $S.ABCD$ đáy hình vuông cạnh $a$, $SA\perp(ABCD)$, $SA=a\sqrt2$. a) hình chiếu của $SC$ lên đáy là $AC$; b) góc giữa $SC$ và đáy là $\widehat{SCA}$; c) góc giữa $SC$ và đáy bằng $45^\circ$; d) góc giữa $SB$ và đáy bằng $60^\circ$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B24-5', 24, 'VD', 'Với dữ kiện trên ($SA=a$, đáy hình vuông cạnh $a$), tính góc giữa $SB$ và $(ABCD)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B24-6', 24, 'VDC', 'Hình lập phương $ABCD.A''B''C''D''$ cạnh $a$. Tính góc giữa $A''C$ và $(ABCD)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B24-7', 24, 'VDC', '*[Trả lời ngắn]* Chóp $S.ABCD$ đáy hình vuông cạnh $a$, $SA\perp(ABCD)$, $SA=a$. Tính $\sin$ góc giữa $SC$ và $(SAB)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B25-1', 25, 'NB', 'Hai mặt phẳng vuông góc có góc bao nhiêu độ?', NULL, 'lop-11/bai-tap'),
  ('BT11-B25-2', 25, 'NB', '*[Trắc nghiệm]* Nếu mặt phẳng $(P)$ chứa một đường thẳng $a$ mà $a\perp(Q)$ thì: A. $(P)\parallel(Q)$; B. $(P)\perp(Q)$; C. $(P)$ trùng $(Q)$; D. $(P)$ và $(Q)$ cắt nhau nhưng không vuông góc.', NULL, 'lop-11/bai-tap'),
  ('BT11-B25-3', 25, 'TH', 'Chóp $S.ABCD$, $SA\perp(ABCD)$. Chứng minh $(SAB)\perp(ABCD)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B25-4', 25, 'TH', '*[Đúng/sai]* Chóp $S.ABCD$ đáy hình vuông, $SA\perp(ABCD)$. a) $(SAB)\perp(ABCD)$; b) $(SAD)\perp(SAB)$; c) $(SAC)\perp(SBD)$; d) $(SBC)\perp(SAC)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B25-5', 25, 'VD', 'Chóp $S.ABCD$ đáy hình vuông cạnh $a$, $SA\perp(ABCD)$, $SA=a\sqrt3$. Tính góc nhị diện $[S,BC,A]$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B25-6', 25, 'VD', '*[Trả lời ngắn]* Chóp $S.ABCD$ đáy hình vuông cạnh $a$, $SA\perp(ABCD)$, $SA=a$. Tính $\tan$ của góc giữa $(SBD)$ và $(ABCD)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B25-7', 25, 'VDC', 'Chóp $S.ABCD$ đáy hình vuông, $SA\perp(ABCD)$. Chứng minh $(SBD)\perp(SAC)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B26-1', 26, 'NB', 'Khoảng cách từ $A''$ đến $(ABCD)$ trong hình lập phương cạnh $a$?', NULL, 'lop-11/bai-tap'),
  ('BT11-B26-2', 26, 'NB', '*[Trắc nghiệm]* Hình lập phương cạnh $a$. Khoảng cách giữa hai mặt phẳng song song $(ABCD)$ và $(A''B''C''D'')$ bằng: A. $a$; B. $a\sqrt2$; C. $\dfrac a2$; D. $a\sqrt3$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B26-3', 26, 'TH', 'Chóp $S.ABC$, $SA\perp(ABC)$, $SA=a$, $\triangle ABC$ vuông tại $B$, $AB=a$. Tính $d(A,(SBC))$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B26-4', 26, 'TH', '*[Đúng/sai]* Chóp $S.ABCD$ đáy hình vuông cạnh $a$, $SA\perp(ABCD)$, $SA=a$. a) $d(S,(ABCD))=a$; b) $d(A,(SBC))=\dfrac{a\sqrt2}2$; c) $d(AB,(SCD))=a$; d) $BC\perp(SAB)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B26-5', 26, 'VD', 'Hình lập phương cạnh $a$. Tính khoảng cách giữa hai đường thẳng chéo nhau $AB$ và $A''D''$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B26-6', 26, 'VDC', 'Tứ diện $OABC$ có $OA,OB,OC$ đôi một vuông góc, $OA=OB=OC=a$. Tính $d(O,(ABC))$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B26-7', 26, 'VDC', '*[Trả lời ngắn]* Chóp $S.ABCD$ đáy hình vuông cạnh $3$, $SA\perp(ABCD)$, $SA=3$. Tính $d(A,(SBD))$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B27-1', 27, 'NB', 'Thể tích chóp đáy vuông cạnh 3, cao 4.', NULL, 'lop-11/bai-tap'),
  ('BT11-B27-2', 27, 'NB', '*[Trắc nghiệm]* Thể tích khối lăng trụ có diện tích đáy $B$ và chiều cao $h$ là: A. $Bh$; B. $\dfrac13Bh$; C. $\dfrac12Bh$; D. $3Bh$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B27-3', 27, 'TH', 'Lăng trụ đứng đáy là tam giác vuông cân cạnh góc vuông $a$, cạnh bên $2a$. Thể tích.', NULL, 'lop-11/bai-tap'),
  ('BT11-B27-4', 27, 'TH', '*[Đúng/sai]* Lăng trụ đứng $ABC.A''B''C''$ có đáy là tam giác vuông tại $A$, $AB=3$, $AC=4$, $AA''=5$. a) $S_{ABC}=6$; b) $V_{ABC.A''B''C''}=30$; c) $V_{A''.ABC}=10$; d) $V_{A.BCC''B''}=15$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B27-5', 27, 'VD', 'Chóp $S.ABCD$ đáy hình vuông cạnh $a$, $SA\perp(ABCD)$, $SC$ tạo với đáy góc $45^\circ$. Tính thể tích.', NULL, 'lop-11/bai-tap'),
  ('BT11-B27-6', 27, 'VD', 'Chóp $S.ABC$, $M$ là trung điểm $SB$, $N\in SC$ với $SN=2NC$. Tính $\dfrac{V_{S.AMN}}{V_{S.ABC}}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B27-7', 27, 'VDC', 'Tính thể tích khối tứ diện đều cạnh $a$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B27-8', 27, 'VDC', '*[Trả lời ngắn]* Chóp $S.ABCD$ đáy hình vuông cạnh $2a$, tam giác $SAB$ đều và nằm trong mặt phẳng vuông góc với đáy. Tính thể tích theo $a$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B31-1', 31, 'NB', 'Đạo hàm của $f(x)=x^2$ tại $x_0=3$ theo định nghĩa.', NULL, 'lop-11/bai-tap'),
  ('BT11-B31-2', 31, 'NB', '*[Trắc nghiệm]* Hệ số góc của tiếp tuyến của đồ thị $y=f(x)$ tại điểm có hoành độ $x_0$ là: A. $f(x_0)$; B. $f''(x_0)$; C. $f''''(x_0)$; D. $\dfrac1{f''(x_0)}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B31-3', 31, 'TH', 'Viết phương trình tiếp tuyến của $y=x^2$ tại điểm có hoành độ 1.', NULL, 'lop-11/bai-tap'),
  ('BT11-B31-4', 31, 'TH', '*[Đúng/sai]* Cho $y=x^3$. a) $y''(1)=3$; b) tiếp tuyến tại điểm có hoành độ $1$ là $y=3x-2$; c) tiếp tuyến đó cắt $Oy$ tại $(0;-2)$; d) hệ số góc tiếp tuyến tại $x=-1$ bằng $-3$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B31-5', 31, 'VD', 'Chất điểm chuyển động có $s(t)=t^2+2t$ (m). Tính vận tốc tại $t=3$ s.', NULL, 'lop-11/bai-tap'),
  ('BT11-B31-6', 31, 'VD', '*[Trả lời ngắn]* Tiếp tuyến của đồ thị $y=x^2-2x$ tại điểm $M$ có hệ số góc bằng $4$. Tìm hoành độ của $M$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B31-7', 31, 'VDC', 'Chứng minh $f(x)=|x|$ không có đạo hàm tại $x=0$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B32-1', 32, 'NB', '$y=x^3-2x+5$. $y''$?', NULL, 'lop-11/bai-tap'),
  ('BT11-B32-2', 32, 'TH', '$y=x\sin x$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B32-3', 32, 'TH', '$y=\dfrac{x+1}{x-1}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B32-4', 32, 'TH', '*[Đúng/sai]* a) $(\sin x)''=\cos x$; b) $(\cos2x)''=-2\sin2x$; c) $(x\ln x)''=\ln x$; d) $(e^{2x})''=2e^{2x}$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B32-5', 32, 'VD', 'Tính đạo hàm của $y=\ln(x^2+1)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B32-6', 32, 'VD', 'Viết phương trình tiếp tuyến của $y=x^3-3x$ tại điểm có hoành độ $2$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B32-7', 32, 'VD', '*[Trả lời ngắn]* Cho $y=x^2e^x$. Tính $y''(1)$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B32-8', 32, 'VDC', 'Tìm $m$ để tiếp tuyến của $y=x^3-mx$ tại điểm có hoành độ $1$ song song với đường thẳng $y=2x+5$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B33-1', 33, 'NB', '$y=x^4-3x$, $y''''$?', NULL, 'lop-11/bai-tap'),
  ('BT11-B33-2', 33, 'NB', '*[Trắc nghiệm]* Đạo hàm cấp hai của $y=x^3$ là: A. $3x^2$; B. $6x$; C. $6$; D. $x^3$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B33-3', 33, 'TH', '$y=\sin2x$. Tính $y''''$ và kiểm tra $y''''+4y=0$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B33-4', 33, 'TH', '*[Đúng/sai]* Cho $y=e^{2x}$. a) $y''=2e^{2x}$; b) $y''''=4e^{2x}$; c) $y''''-2y''=0$; d) $y''''+y''=0$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B33-5', 33, 'VD', 'Chuyển động có $s(t)=t^3-3t^2+2t$. Tính gia tốc tại $t=2$.', NULL, 'lop-11/bai-tap'),
  ('BT11-B33-6', 33, 'VD', '*[Trả lời ngắn]* Chuyển động có $s(t)=2t^3-9t^2+12t$ ($t$ giây). Tại thời điểm nào gia tốc bằng $0$?', NULL, 'lop-11/bai-tap'),
  ('BT11-B33-7', 33, 'VDC', 'Chứng minh hàm số $y=xe^x$ thỏa mãn $y''''-2y''+y=0$.', NULL, 'lop-11/bai-tap'),
  ('BM-001', 24, 'TH', 'Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình vuông cạnh $a$, $SA\perp(ABCD)$ và $SA=a\sqrt6$. Tính góc giữa đường thẳng $SC$ và mặt phẳng $(ABCD)$.', '$60^\circ$', 'baseline/bo-mau'),
  ('BM-002', 24, 'VD', 'Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình vuông cạnh $a$, $SA\perp(ABCD)$ và $SA=a\sqrt2$. Tính góc giữa đường thẳng $SC$ và mặt phẳng $(SAB)$.', '$30^\circ$', 'baseline/bo-mau'),
  ('BM-003', 24, 'TH', 'Cho hình chóp tứ giác đều $S.ABCD$ có cạnh đáy $a$, $O$ là tâm đáy và $SO=\dfrac{a\sqrt6}{2}$. Tính góc giữa cạnh bên $SA$ và mặt đáy.', '$60^\circ$', 'baseline/bo-mau'),
  ('BM-004', 22, 'TH', 'Cho hình lập phương $ABCD.A''B''C''D''$ cạnh $a$. Tính góc giữa hai đường thẳng $AB''$ và $AD''$.', '$60^\circ$', 'baseline/bo-mau'),
  ('BM-005', 24, 'TH', 'Cho hình hộp chữ nhật $ABCD.A''B''C''D''$ có $AB=a$, $AD=a\sqrt3$, $AA''=2a$. Tính góc giữa đường chéo $AC''$ và mặt phẳng $(ABCD)$.', '$45^\circ$', 'baseline/bo-mau'),
  ('BM-006', 24, 'TH', 'Cho lăng trụ đứng $ABC.A''B''C''$ có đáy là tam giác vuông tại $A$, $AB=a$, $AC=a\sqrt3$, $AA''=2a$. Tính góc giữa đường thẳng $B''C$ và mặt phẳng $(ABC)$.', '$45^\circ$', 'baseline/bo-mau'),
  ('BM-007', 26, 'TH', 'Cho hình chóp $S.ABCD$ có đáy là hình vuông cạnh $a$, $SA\perp(ABCD)$ và $SA=a$. Tính khoảng cách từ $A$ đến mặt phẳng $(SBC)$.', '$\dfrac{a\sqrt2}{2}$', 'baseline/bo-mau'),
  ('BM-008', 26, 'VD', 'Cho hình chóp $S.ABCD$ có đáy là hình vuông cạnh $a$, $SA\perp(ABCD)$ và $SA=a\sqrt3$. Tính khoảng cách giữa hai đường thẳng $AB$ và $SD$.', '$\dfrac{a\sqrt3}{2}$', 'baseline/bo-mau'),
  ('BM-009', 26, 'VD', 'Cho hình chóp $S.ABCD$ có đáy là hình vuông cạnh $a$, $SA\perp(ABCD)$, $SA=a$. Tính khoảng cách giữa hai đường thẳng chéo nhau $BD$ và $SC$.', '$\dfrac{a\sqrt6}{6}$', 'baseline/bo-mau'),
  ('BM-010', 26, 'VDC', 'Cho hình chóp tứ giác đều $S.ABCD$ có tất cả các cạnh bằng $a$. Tính khoảng cách giữa hai đường thẳng $AB$ và $SC$.', '$\dfrac{a\sqrt6}{3}$', 'baseline/bo-mau'),
  ('BM-011', 26, 'TH', 'Hình chóp tứ giác đều $S.ABCD$ có cạnh đáy $6$ cm, chiều cao $SO=4$ cm. Tính khoảng cách từ tâm đáy $O$ đến mặt bên $(SBC)$.', '$2{,}4$ cm', 'baseline/bo-mau'),
